import { execFileSync } from 'node:child_process';
import { mkdtempSync, rmSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { expect, test } from '@playwright/test';

/**
 * The converter is gated on a key. These tests seed one so the UI unlocks and
 * run against an API started with CONVERT_AUTH=off, so no database is needed —
 * the gate itself has 11 server-side tests of its own.
 */
const TEST_KEY = 'helix-aaaaaaaaaaaaaaaa';

/**
 * Drives the real UI against the real API. Fixtures are generated by ffmpeg so
 * the repo carries no binaries.
 */
let dir: string;
let clip: string;
let image: string;

test.beforeEach(async ({ page }) => {
  // Runs on every navigation, so it honours an explicit sign-out rather than
  // re-seeding the key on the next reload.
  await page.addInitScript(
    (key) => {
      try {
        if (window.localStorage.getItem('converter:signed-out') === '1') return;
        window.localStorage.setItem('converter:key', key);
      } catch {
        /* private mode */
      }
    },
    TEST_KEY,
  );
});

test.beforeAll(() => {
  dir = mkdtempSync(join(tmpdir(), 'converter-e2e-'));
  clip = join(dir, 'clip.mp4');
  image = join(dir, 'photo.png');

  execFileSync('ffmpeg', [
    '-hide_banner', '-nostdin', '-y',
    '-f', 'lavfi', '-i', 'testsrc=size=320x240:rate=15:duration=2',
    '-f', 'lavfi', '-i', 'sine=frequency=440:duration=2',
    '-c:v', 'libx264', '-pix_fmt', 'yuv420p', '-c:a', 'aac', '-shortest', clip,
  ]);
  execFileSync('ffmpeg', [
    '-hide_banner', '-y', '-f', 'lavfi', '-i', 'testsrc=size=400x300:duration=1',
    '-frames:v', '1', image,
  ]);
});

test.afterAll(() => {
  rmSync(dir, { recursive: true, force: true });
});

test('converts a video end to end and offers the result', async ({ page }) => {
  const errors: string[] = [];
  page.on('console', (m) => m.type() === 'error' && errors.push(m.text()));
  page.on('pageerror', (e) => errors.push(String(e)));

  await page.goto('/convert');
  await expect(page.getByRole('heading', { name: 'Convert a file' })).toBeVisible();

  await page.locator('input[type=file]').first().setInputFiles(clip);
  await expect(page.getByText('clip.mp4')).toBeVisible();

  await page.getByRole('button', { name: /^convert/i }).last().click();

  // The download affordance is the completion signal.
  const download = page
    .getByRole('link', { name: /download/i })
    .or(page.getByRole('button', { name: /download/i }))
    .first();
  await expect(download).toBeVisible({ timeout: 90_000 });

  // A CORS or SSE regression shows up here, not in a server-side test.
  expect(errors, `console errors: ${errors.join(' | ')}`).toHaveLength(0);
});

test('converts an image through the sharp path', async ({ page }) => {
  await page.goto('/convert');
  await page.locator('input[type=file]').first().setInputFiles(image);
  await expect(page.getByText('photo.png')).toBeVisible();

  await page.getByRole('button', { name: /^convert/i }).last().click();
  await expect(
    page.getByRole('link', { name: /download/i }).or(page.getByRole('button', { name: /download/i })).first(),
  ).toBeVisible({ timeout: 60_000 });
});

test('rejects a file that is not media, and says why in plain language', async ({ page }) => {
  const junk = join(dir, 'notes.mp4');
  const { writeFileSync } = await import('node:fs');
  writeFileSync(junk, 'this is not a video');

  await page.goto('/convert');
  await page.locator('input[type=file]').first().setInputFiles(junk);
  await page.getByRole('button', { name: /^convert/i }).last().click();

  await expect(page.getByText(/couldn't|can't|corrupt|failed/i).first()).toBeVisible({
    timeout: 60_000,
  });
});

test('the command palette finds a tool by name', async ({ page }) => {
  await page.goto('/');
  await page.keyboard.press('ControlOrMeta+k');

  const search = page.getByRole('combobox').or(page.getByPlaceholder(/search/i)).first();
  await expect(search).toBeVisible();
  await search.fill('mp3');
  await expect(page.getByRole('option').first()).toBeVisible();

  await page.keyboard.press('Escape');
  await expect(search).toBeHidden();
});

test('every page carries the same header and footer', async ({ page }) => {
  for (const path of ['/', '/convert', '/convert/mp4-to-mp3', '/tools', '/history', '/api-docs']) {
    await page.goto(path);
    await expect(page.getByRole('banner'), `header missing on ${path}`).toBeVisible();
    await expect(page.getByRole('contentinfo'), `footer missing on ${path}`).toBeVisible();
  }
});

test('the converter is operable by keyboard alone', async ({ page }) => {
  await page.goto('/convert');

  // The dropzone must be reachable and focusable without a pointer.
  await page.keyboard.press('Tab');
  const focused = await page.evaluate(() => document.activeElement?.tagName);
  expect(focused).toBeTruthy();

  const dropzone = page.getByRole('button', { name: /drop files/i });
  await dropzone.focus();
  await expect(dropzone).toBeFocused();
});

async function signOut(page: import('@playwright/test').Page) {
  await page.goto('/convert');
  await page.evaluate(() => {
    window.localStorage.setItem('converter:signed-out', '1');
    window.localStorage.removeItem('converter:key');
  });
  await page.reload({ waitUntil: 'networkidle' });
}

test('shows the sign-in panel when there is no key', async ({ page }) => {
  await signOut(page);
  await expect(page.getByRole('heading', { name: /sign in to convert/i })).toBeVisible();
  await expect(page.getByLabel(/helix api key/i)).toBeVisible();
});

test('a saved key unlocks the converter and shows in the header', async ({ page }) => {
  // The header badge is sm:inline-flex, so it needs a desktop width.
  await page.setViewportSize({ width: 1280, height: 800 });
  await page.goto('/convert');

  await expect(page.getByRole('button', { name: /drop files/i })).toBeVisible();
  await expect(page.getByRole('heading', { name: /sign in to convert/i })).toBeHidden();
  // The badge masks the key rather than printing it.
  const badge = page.getByRole('button', { name: /forget this key/i });
  await expect(badge).toBeVisible();
  // The full key must never be rendered, in text or in the accessible name.
  await expect(badge).not.toHaveText(TEST_KEY);
  await expect(badge).not.toHaveAccessibleName(new RegExp(TEST_KEY));
});

test('rejects a key that is not the Helix shape', async ({ page }) => {
  await signOut(page);
  await page.getByLabel(/helix api key/i).fill('not-a-real-key');
  await page.getByRole('button', { name: /save key/i }).click();

  // KeyGate renders in more than one place, so scope to the first alert.
  await expect(page.getByRole('alert').first()).toBeVisible();
  await expect(page.getByRole('heading', { name: /sign in to convert/i })).toBeVisible();
  // The invalid key must not have been stored.
  expect(await page.evaluate(() => window.localStorage.getItem('converter:key'))).toBeNull();
});

test('settings shows the key, the service state, and real provider marks', async ({ page }) => {
  await page.goto('/settings');

  await expect(page.getByRole('heading', { name: 'Settings' })).toBeVisible();
  await expect(page.getByRole('heading', { name: 'API key' })).toBeVisible();

  // The endpoint the client actually talks to, not a hardcoded string.
  await expect(page.getByText('http://localhost:8400')).toBeVisible();

  // Every provider wears a real mark that loaded; a broken image has
  // naturalWidth 0 and would otherwise render as a silent gap.
  const marks = page.locator('img[src^="/providers"]');
  await expect(marks).toHaveCount(6);
  const widths = await marks.evaluateAll((imgs) =>
    imgs.map((i) => (i as HTMLImageElement).naturalWidth),
  );
  expect(widths.every((w) => w > 0), `broken marks: ${widths.join(',')}`).toBe(true);

  // The sound switch is a real control, not decoration.
  const sound = page.getByRole('switch');
  await expect(sound).toBeVisible();
  const before = await sound.getAttribute('aria-checked');
  await sound.click();
  await expect(sound).not.toHaveAttribute('aria-checked', before ?? '');
});

test('every provider mark is a distinct file, so none wears another brand', async ({ page }) => {
  await page.goto('/settings');
  const srcs = await page
    .locator('img[src^="/providers"]')
    .evaluateAll((imgs) => imgs.map((i) => (i as HTMLImageElement).getAttribute('src')));

  expect(new Set(srcs).size).toBe(srcs.length);
});
